<script lang="ts">
  import { onMount } from "svelte";
  import { initMieleFilter } from "./miele-filter.js";

  let { title }: { title?: string } = $props();
  let root: HTMLElement;
  let currentStep = $state(3);
  let controller: { setStop: (idx: number) => void; cleanup: () => void } | null = null;

  onMount(() => {
    controller = initMieleFilter(root, (idx: number) => {
      currentStep = idx;
    });
    return () => {
      controller?.cleanup();
    };
  });

  function chooseStep(idx: number) {
    currentStep = idx;
    controller?.setStop(idx);
  }
</script>

