<style>
  .miele-filter-wrapper {
    margin: 1.5rem 0;
    border: 1px solid var(--rule);
    border-radius: var(--radius-sm);
    background: var(--surface);
    overflow: hidden;
  }

  .stepper-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.6rem 0.8rem;
    border-bottom: 1px solid var(--rule);
    background: var(--surface-subtle, var(--surface));
  }

  .stepper-label {
    font-size: var(--text-sm);
    font-weight: 500;
    color: var(--text-primary);
  }

  .stepper-buttons {
    display: flex;
    gap: 0.35rem;
  }

  .stepper-buttons button.active {
    background: var(--primary);
    color: var(--primary-contrast, #fff);
  }

  /* Scoped anatomy figure styles */
  .miele-filter-wrapper :global(.iso-figure) {
    margin: 0;
  }

  .miele-filter-wrapper :global(.iso-plate) {
    position: relative;
    padding: 48px 20px 40px;
    background: transparent;
    box-shadow: none;
  }

  .miele-filter-wrapper :global(.iso-plate-corners) {
    position: absolute;
    inset: 14px 18px;
    pointer-events: none;
  }

  .miele-filter-wrapper :global(.iso-plate-corner) {
    position: absolute;
    color: var(--text-secondary);
    font-family: var(--font-mono);
    font-size: var(--text-2xs);
    line-height: 1;
    letter-spacing: .04em;
    white-space: nowrap;
  }

  .miele-filter-wrapper :global(.iso-plate-corner[data-corner="fig"]) {
    top: 0;
    left: 0;
    color: var(--text-primary);
  }

  .miele-filter-wrapper :global(.iso-plate-corner[data-corner="title"]) {
    top: 0;
    right: 0;
    text-transform: uppercase;
    letter-spacing: .1em;
  }

  .miele-filter-wrapper :global(.iso-plate-corner[data-corner="hint"]) {
    bottom: 0;
    left: 0;
    text-transform: uppercase;
    letter-spacing: .1em;
  }

  .miele-filter-wrapper :global(.iso-plate-corner[data-corner="readout"]) {
    right: 0;
    bottom: 0;
    color: var(--text-primary);
    font-variant-numeric: tabular-nums;
  }

  .miele-filter-wrapper :global(.iso-svg) {
    display: block;
    width: 100%;
    height: auto;
    max-height: 480px;
    margin: 0 auto;
    overflow: visible;
  }

  .miele-filter-wrapper :global(.iso-svg path),
  .miele-filter-wrapper :global(.iso-svg circle) {
    vector-effect: non-scaling-stroke;
  }

  .miele-filter-wrapper :global(.iso-fill) {
    fill: var(--surface);
    stroke: none;
  }

  .miele-filter-wrapper :global(.iso-shade[data-shade="0"]) { fill: var(--anatomy-shade-0, #151515); }
  .miele-filter-wrapper :global(.iso-shade[data-shade="1"]) { fill: var(--anatomy-shade-1, #1e1e1e); }
  .miele-filter-wrapper :global(.iso-shade[data-shade="2"]) { fill: var(--anatomy-shade-2, #262626); }
  .miele-filter-wrapper :global(.iso-shade[data-shade="3"]) { fill: var(--anatomy-shade-3, #303030); }
  .miele-filter-wrapper :global(.iso-top) { fill: var(--anatomy-top, #383838); }

